// Nilad F7 — evaluate one store health-check response (pure; unit-tested in n8n/tests/cases/f7.cases.js).
// Input: HTTP Request full-response item { json: { statusCode, body?, headers?, request? } },
//        or an error-ish item { json: { error?, message?, body?, ... } } when the request itself failed.
// Env: none in this node — STORE_URL is consumed by the upstream HTTP Request node.
// Outputs ONE item: { healthy, statusCode, reason, checkedAt }
//   reason: 'ok' (200-399) | 'http-<code>' (>=400) | 'request-failed' (no/invalid status, json.error, connection failure)
const json = ($input.first() || {}).json || {};

let statusCode = null;
const raw = json.statusCode;
if (typeof raw === 'number' && Number.isFinite(raw)) {
  statusCode = Math.trunc(raw);
} else if (typeof raw === 'string' && /^\s*\d{1,4}\s*$/.test(raw)) {
  statusCode = Number(raw.trim());
}

let bodyText = '';
if (typeof json.body === 'string') {
  bodyText = json.body;
} else if (json.body !== undefined && json.body !== null) {
  try {
    bodyText = JSON.stringify(json.body);
  } catch (err) {
    bodyText = '';
  }
}
const messageText = typeof json.message === 'string' ? json.message : '';
const errorPresent = json.error !== undefined && json.error !== null && json.error !== '';
const connectionFailed = /ECONNREFUSED|ECONNRESET|ETIMEDOUT|EAI_AGAIN|ENOTFOUND|EPIPE|getaddrinfo|socket hang up|Connection refused|Connection reset|Could not connect|Connection error/i.test(
  bodyText + ' ' + messageText
);

let healthy = false;
let reason = 'request-failed';
if (!errorPresent && !connectionFailed && statusCode !== null) {
  if (statusCode >= 200 && statusCode <= 399) {
    healthy = true;
    reason = 'ok';
  } else if (statusCode >= 400) {
    reason = 'http-' + statusCode;
  }
}

return [{ json: { healthy, statusCode, reason, checkedAt: new Date().toISOString() } }];
